document.addEventListener("DOMContentLoaded",function(){showAnswer(1);});function showAnswer(index){document.querySelectorAll('.faq-item').forEach(item=>item.classList.remove('active'));document.querySelectorAll('.faq-answer, .mobile-faq-answer').forEach(answer=>answer.style.display='none');document.querySelectorAll('.faq-item')[index-1].classList.add('active');let desktopAnswer=document.getElementById(`faq-answer-${index}`);if(desktopAnswer)desktopAnswer.style.display='block';let mobileAnswer=document.getElementById(`mobile-faq-answer-${index}`);if(mobileAnswer)mobileAnswer.style.display='block';}